<script setup>
import { reactive, ref } from 'vue'; import UserLayout from '../../layouts/UserLayout.vue'; import PageHeader from '../../components/common/PageHeader.vue'; import { createPasswordForm, handlePasswordChange, passwordFields, profileFields, validatePasswordChange } from '../../data/common/profile'
const form=reactive(createPasswordForm()); const errors=ref({}); const message=ref(''); function submit(){errors.value=validatePasswordChange(form); if(handlePasswordChange(form).ok){message.value='密码修改演示已完成'; Object.assign(form,createPasswordForm())}}
</script>
<template><UserLayout><div class="page-content"><PageHeader title="个人信息" description="查看账号资料并管理登录密码" /><div class="profile-grid"><section class="panel"><div class="panel-heading"><h2 class="panel-title">基本资料</h2></div><dl class="profile-list"><div v-for="item in profileFields" :key="item.label"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></div></dl><div class="profile-actions"><button class="button" type="button">退出登录</button></div></section><form class="panel password-panel" @submit.prevent="submit"><div class="panel-heading"><h2 class="panel-title">修改密码</h2></div><div class="panel-body"><label v-for="field in passwordFields" :key="field.key"><span class="field-label">{{ field.label }}</span><input v-model="form[field.key]" class="input" type="password" :placeholder="field.placeholder"><span class="field-error">{{ errors[field.key] }}</span></label><p v-if="message" class="success-message">{{ message }}</p><button class="button button-primary" type="submit">保存新密码</button></div></form></div></div></UserLayout></template>
<style scoped>.profile-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.profile-list{padding:4px 18px}.profile-list div{display:grid;grid-template-columns:120px 1fr;padding:16px 0;border-bottom:1px solid var(--color-border)}dt{color:var(--color-text-secondary)}dd{margin:0;color:var(--color-primary-900)}.profile-actions{display:flex;justify-content:flex-end;padding:18px}.success-message{margin:0 0 14px;color:var(--color-success)}@media(max-width:820px){.profile-grid{grid-template-columns:1fr}.profile-list div{grid-template-columns:100px 1fr}}</style>
